<?php $labels=['draft'=>'Rascunho','sent'=>'Enviado','viewed'=>'Visualizado','signed'=>'Assinado','cancelled'=>'Cancelado']; ?><style>.contract-document pre{margin:0;white-space:pre-wrap;font:400 1rem/1.65 Georgia,serif}.contract-document{min-height:38rem}.input-copy-row{display:grid;grid-template-columns:1fr auto;gap:.5rem}.input-copy-row>*{margin:0!important}</style>
