<?php if(in_array($contract['status'],['sent','viewed','signed'],true)):?><section class="card mt-4"><h2>Link de assinatura</h2><div class="input-copy-row"><input id="contract-public-url" readonly value="<?= $escape($publicUrl) ?>"><button class="button button-secondary button-icon" type="button" data-copy-target="contract-public-url" title="Copiar"><i class="fa-solid fa-copy"></i></button></div><small>Envie somente ao representante autorizado.</small></section><?php endif;?>
<?php if($contract['status']==='signed'):?><section class="card mt-4"><h2>Evidências</h2><p><strong><?= $escape($contract['signer_name']) ?></strong><br><?= $escape($contract['signer_email']) ?><br>Documento <?= $escape($contract['signer_document']) ?></p><p><small>IP <?= $escape($contract['signer_ip']) ?></small></p><label>Código de integridade<input readonly value="<?= $escape($contract['evidence_hash']) ?>"></label><button class="button button-secondary" type="button" onclick="window.print()"><i class="fa-solid fa-print"></i> Imprimir / salvar PDF</button></section><?php endif;?></aside></div>
